def lcs(str1, str2):
    def lcs_recursive(s1, s2, i, j):
        if i == 0 or j == 0:
            return ""
        if s1[i - 1] == s2[j - 1]:
            return lcs_recursive(s1, s2, i - 1, j - 1) + s1[i - 1]
        else:
            return max(lcs_recursive(s1, s2, i - 1, j), lcs_recursive(s1, s2, i, j - 1), key=len)

    if not any(char in str2 for char in str1):
        return ""
    return max(lcs_recursive(str1, str2, i, j) for i in range(len(str1) + 1) for j in range(len(str2) + 1))

# Example usage:
